// Pick out the recording the form asked for and hand the tracker the same
// shape Fathom's webhook sends, plus force_score.
//
// A Fathom key only ever reaches its OWN owner's recordings, so every closer's
// account has to be asked separately and the answers pooled. Reading each
// source defensively matters: a key that is missing or broken must not hide
// the accounts that do work, and the not-found message names what came back
// from each one so a missing key looks like a missing key rather than a bad ID.
//
// This is a Code node, not an expression on the HTTP body, deliberately: a
// throw inside an n8n expression is swallowed and the body becomes the string
// "undefined", so the only error names the wrong node and the wrong problem.
const form = $('Score a call').first().json;
const raw = String(form.recording || '').trim();
if (!raw) { throw new Error('No recording was given.'); }
const idM = raw.match(/[0-9]{6,}/);
const id = idM ? idM[0] : null;
const tail = raw.indexOf('/') > -1 ? raw.split('/').pop().split('?')[0] : null;

const sources = __FATHOM_SOURCES__;
let list = [];
const seen = [];
for (const s of sources) {
  let items = [];
  try {
    items = ($(s).all() || []).reduce(function (acc, i) { return acc.concat(i.json.items || i.json.data || []); }, []);
  } catch (e) { items = []; }
  list = list.concat(items);
  const owners = items.map(function (i) { return (i.recorded_by || {}).name; }).filter(Boolean);
  const who = owners.length ? ' (' + owners.filter(function (v, n, a) { return a.indexOf(v) === n; }).join(', ') + ')' : '';
  seen.push(s.replace('Ask Fathom - ', '') + ': ' + items.length + who);
}

const m = list.find(function (x) { return (id && String(x.recording_id) === id) || (tail && String(x.share_url || '').endsWith(tail)); });
if (!m) { throw new Error('Could not find that recording. Searched ' + list.length + ' recordings from the last __WINDOW_DAYS__ days - ' + seen.join('; ') + '. A Fathom key only sees its own owner calls, so if the closer who recorded it is not listed above, their key is not attached to this workflow.'); }

// The same floor the tracker's "Has Transcript?" gate uses. Caught here rather
// than downstream so the person at the form is told why, instead of the call
// silently becoming a No show row they have to go and find.
const words = (m.transcript || []).map(function (t) { return t.text || ''; }).join(' ').split(/\s+/).filter(Boolean).length;
if (words < __MIN_TRANSCRIPT_WORDS__) { throw new Error('That recording has only ' + words + ' words of transcript, so there is nothing to score. It is almost certainly a no-show.'); }

const body = Object.assign({}, m, { force_score: true });
const name = String(form.prospect_name || '').trim();
if (name) { const t = String(m.meeting_title || m.title || ''); const after = t.indexOf(':') > 0 ? t.slice(t.indexOf(':') + 1).trim() : t; body.meeting_title = name + ': ' + after; }
return [{ json: body }];
